-- Full mock data: 3-4 stations per province, all 77 Thai provinces
-- Clear existing mock stations
DELETE FROM fuel_status;
DELETE FROM stations;
SELECT setval('stations_id_seq', 1, false);


-- Fuel status: 3 fuel types per station with varied inventory
SELECT
    s.id,
    ft.fuel_type,
    (ARRAY['high','high','high','medium','medium','low','out','refilling'])[ ((s.id * 3 + ft.ord) % 8) + 1 ],
    CASE
        WHEN (ARRAY['high','high','high','medium','medium','low','out','refilling'])[ ((s.id*3+ft.ord)%8)+1 ] = 'high'      THEN 7000 + (s.id * 113) % 6000
        WHEN (ARRAY['high','high','high','medium','medium','low','out','refilling'])[ ((s.id*3+ft.ord)%8)+1 ] = 'medium'    THEN 2500 + (s.id * 97)  % 2500
        WHEN (ARRAY['high','high','high','medium','medium','low','out','refilling'])[ ((s.id*3+ft.ord)%8)+1 ] = 'low'       THEN  300 + (s.id * 53)  % 1200
        WHEN (ARRAY['high','high','high','medium','medium','low','out','refilling'])[ ((s.id*3+ft.ord)%8)+1 ] = 'refilling' THEN  100 + (s.id * 31)  %  400
        ELSE 0
    END,
    ft.base_price + ((s.id % 10) * 0.1),
    'mock_seed',
    'auto-generated mock data',
    s.last_updated - (ft.ord * INTERVAL '2 minutes')
FROM stations s
CROSS JOIN (VALUES
    ('Gasohol 95', 1, 39.00),
    ('Gasohol 91', 2, 37.80),
    ('Diesel B7',  3, 32.00)
) AS ft(fuel_type, ord, base_price);
-- Samut Songkhram: add 3rd station (province has only 3 districts)
VALUES (761, 'Shell Amphawa Canal Road', 'Shell', 'Amphawa, Samut Songkhram', 13.4222, 100.0012, NOW() - INTERVAL '45 minutes');

SELECT s.id, ft.fuel_type,
  (ARRAY['high','medium','low'])[ft.ord],
  CASE ft.ord WHEN 1 THEN 8500 WHEN 2 THEN 3200 ELSE 600 END,
  ft.base_price, 'mock_seed', 'auto-generated', NOW() - INTERVAL '47 minutes'
FROM stations s
CROSS JOIN (VALUES ('Gasohol 95',1,39.10),('Gasohol 91',2,37.90),('Diesel B7',3,32.10)) AS ft(fuel_type,ord,base_price)
WHERE s.name='Shell Amphawa Canal Road';
